   197|function isToday(iso: string | null): boolean {
   198|  if (!iso) return false;
   199|  try {
   200|    return new Date(iso).toISOString().slice(0, 10) === new Date().toISOString().slice(0, 10);
   201|  } catch {
   202|    return false;
   203|  }
