   206|function mapAgentRunStatus(status: AgentRun['status']): AgentStatus {
   207|  switch (status) {
   208|    case 'running': return 'RUNNING';
   209|    case 'completed': return 'COMPLETED';
   210|    case 'failed': return 'FAILED';
   211|    default: return 'IDLE';
   212|  }
   213|}
