   215|function categorizeAgentRun(run: AgentRun): ActivityCategory {
   216|  switch (run.kind) {
   217|    case 'opportunity_scan': return 'INVESTORS';
   218|    case 'innovation_scan': return 'AUTONOMOUS_SYSTEM';
   219|    case 'qa_scan': return 'DEVELOPMENT';
   220|    case 'capital_matching': return 'INVESTORS';
   221|    case 'learning_cycle': return 'AUTONOMOUS_SYSTEM';
   222|    case 'supabase_check': return 'DEVELOPMENT';
   223|    case 'self_improvement': return 'AUTONOMOUS_SYSTEM';
   224|    default: return 'AUTONOMOUS_SYSTEM';
   225|  }
   226|}
