   228|function deriveAgentStatus(runs: AgentRun[], agentId: string): { status: AgentStatus; currentTask: string | null; lastActivity: string | null } {
   229|  const agentRuns = runs.filter((r) => r.label.toLowerCase().includes(agentId.replace(/_/g, ' ')) || r.kind === agentId);
   230|  const running = agentRuns.find((r) => r.status === 'running');
   231|  if (running) {
   232|    return { status: 'RUNNING', currentTask: running.detail, lastActivity: running.startedAt };
   233|  }
   234|  const latest = agentRuns[0];
   235|  if (latest) {
   236|    return {
   237|      status: latest.status === 'completed' ? 'COMPLETED' : latest.status === 'failed' ? 'FAILED' : 'IDLE',
   238|      currentTask: latest.proof ?? latest.detail,
   239|      lastActivity: latest.finishedAt ?? latest.startedAt,
   240|    };
   241|  }
   242|  return { status: 'IDLE', currentTask: null, lastActivity: null };
   243|}
   244|
   245|function countAgentRunsToday(runs: AgentRun[], agentId: string): { started: number; completed: number; failed: number; blocked: number } {
   246|  const todayRuns = runs.filter((r) =>
   247|    isToday(r.startedAt) &&
   248|    (r.label.toLowerCase().includes(agentId.replace(/_/g, ' ')) || r.kind === agentId)
   249|  );
   250|  return {
   251|    started: todayRuns.length,
   252|    completed: todayRuns.filter((r) => r.status === 'completed').length,
   253|    failed: todayRuns.filter((r) => r.status === 'failed').length,
   254|    blocked: todayRuns.filter((r) => r.status === 'failed' && (r.error ?? '').includes('block')).length,
   255|  };
   256|}
   257|
   258|function computeSuccessRate(runs: AgentRun[], agentId: string): number | null {
   259|  const agentRuns = runs.filter((r) =>
   260|    r.label.toLowerCase().includes(agentId.replace(/_/g, ' ')) || r.kind === agentId
   261|  );
   262|  const finished = agentRuns.filter((r) => r.status === 'completed' || r.status === 'failed');
   263|  if (finished.length === 0) return null;
   264|  const completed = finished.filter((r) => r.status === 'completed').length;
   265|  return Math.round((completed / finished.length) * 100);
   266|}
   267|
   268|function computeTotalExecTime(runs: AgentRun[], agentId: string): number | null {
   269|  const agentRuns = runs.filter((r) =>
   270|    r.label.toLowerCase().includes(agentId.replace(/_/g, ' ')) || r.kind === agentId
   271|  );
   272|  const durations = agentRuns.filter((r) => r.durationMs !== null).map((r) => r.durationMs as number);
   273|  if (durations.length === 0) return null;
   274|  return durations.reduce((a, b) => a + b, 0);
   275|}
