   308|export async function handleAutonomousOpsDashboardRequest(request: Request): Promise<Response> {
   309|  try {
   310|    await assertIVXOwnerOnly(request);
   311|  } catch (err) {
   312|    const message = err instanceof Error ? err.message : 'unauthorized';
   313|    return ownerOnlyJson({ ok: false, error: message }, 401);
   314|  }
   315|
   316|  const url = new URL(request.url);
   317|  const rangeParam = url.searchParams.get('range') ?? 'today';
   318|  const agentFilter = url.searchParams.get('agent') ?? null;
   319|  const categoryFilter = url.searchParams.get('category') ?? null;
   320|
   321|  const now = new Date();
   322|  let rangeStart: string;
   323|  let rangeEnd: string = now.toISOString();
   324|  let rangeLabel: string;
   325|
   326|  switch (rangeParam) {
   327|    case 'yesterday': {
   328|      const y = new Date(now);
   329|      y.setUTCDate(y.getUTCDate() - 1);
   330|      y.setUTCHours(0, 0, 0, 0);
   331|      rangeStart = y.toISOString();
   332|      const ye = new Date(y);
   333|      ye.setUTCHours(23, 59, 59, 999);
   334|      rangeEnd = ye.toISOString();
   335|      rangeLabel = 'Yesterday';
   336|      break;
   337|    }
   338|    case '7d': {
   339|      const s = new Date(now);
   340|      s.setUTCDate(s.getUTCDate() - 7);
   341|      rangeStart = s.toISOString();
   342|      rangeLabel = 'Last 7 days';
   343|      break;
   344|    }
   345|    case '30d': {
   346|      const s = new Date(now);
   347|      s.setUTCDate(s.getUTCDate() - 30);
   348|      rangeStart = s.toISOString();
   349|      rangeLabel = 'Last 30 days';
   350|      break;
   351|    }
   352|    case 'today':
   353|    default:
   354|      rangeStart = todayStart();
   355|      rangeLabel = 'Today';
   356|      break;
   357|  }
   358|
   359|  // Fetch all data sources in parallel
   360|  const [agentRuns, latestReport, reportHistory, ownerActions, proofLedger] = await Promise.all([
   361|    listAgentRuns(200),
   362|    getLatestReport(),
   363|    listReportHistory(7),
   364|    readOwnerActionRequests(),
   365|    readProofLedgerRecent(),
   366|  ]);
   367|
   368|  // Build unified agent list — merge 14 enterprise + 12 executive (dedup by id)
   369|  const allAgentIds = new Set<string>([...ENTERPRISE_AGENT_IDS, ...EXECUTIVE_AGENT_IDS]);
   370|  const agents: UnifiedAgent[] = [];
   371|  let agentNumber = 0;
   372|
   373|  for (const agentId of allAgentIds) {
   374|    agentNumber++;
   375|    const entDef = ENTERPRISE_AGENTS[agentId as EnterpriseAgentId];
   376|    const execDef = EXECUTIVE_AGENTS[agentId as ExecutiveAgentId];
   377|    const name = entDef?.name ?? execDef?.name ?? agentId;
   378|    const role = entDef?.role ?? execDef?.role ?? '';
   379|    const dept = DEPARTMENT_MAP[agentId] ?? 'Operations';
   380|
   381|    const { status, currentTask, lastActivity } = deriveAgentStatus(agentRuns, agentId);
   382|    const counts = countAgentRunsToday(agentRuns, agentId);
   383|    const successRate = computeSuccessRate(agentRuns, agentId);
   384|    const totalExec = computeTotalExecTime(agentRuns, agentId);
   385|
   386|    agents.push({
   387|      agentNumber,
   388|      agentId,
   389|      name,
   390|      department: dept,
   391|      primaryResponsibility: role,
   392|      status,
   393|      currentTask,
   394|      tasksStartedToday: counts.started,
   395|      tasksCompletedToday: counts.completed,
   396|      tasksFailedToday: counts.failed,
   397|      tasksBlockedToday: counts.blocked,
   398|      lastActivityTime: lastActivity,
   399|      totalExecutionTimeMs: totalExec,
   400|      successRate,
   401|      evidenceLink: `/api/ivx/live-work/agents`,
   402|      traceId: null,
   403|    });
   404|  }
   405|
   406|  // Build activity items from agent runs
   407|  const activityItems: ActivityItem[] = [];
   408|  let itemNum = 0;
   409|
   410|  for (const run of agentRuns) {
   411|    itemNum++;
   412|    const category = categorizeAgentRun(run);
   413|    const status = mapAgentRunStatus(run.status);
   414|
   415|    activityItems.push({
   416|      itemNumber: itemNum,
   417|      agent: run.label,
   418|      department: DEPARTMENT_MAP[run.kind] ?? 'Autonomous',
   419|      category,
   420|      task: run.why,
   421|      actionExecuted: run.detail,
   422|      result: run.proof ?? run.error ?? 'In progress',
   423|      status,
   424|      startTime: run.startedAt,
   425|      endTime: run.finishedAt,
   426|      durationMs: run.durationMs,
   427|      repository: 'ibb142/rork-global-real-estate-invest',
   428|      branch: 'main',
   429|      commitSha: null,
   430|      deploymentId: null,
   431|      productionUrl: 'https://api.ivxholding.com',
   432|      investorId: null,
   433|      propertyId: null,
   434|      leadId: null,
   435|      error: run.error,
   436|      retryCount: 0,
   437|      evidence: run.proof ? `Agent run ${run.id}: ${run.proof}` : `Agent run ${run.id}`,
   438|      traceId: run.id,
   439|    });
   440|  }
   441|
   442|  // Add proof ledger entries as activity items
   443|  for (const proof of proofLedger) {
   444|    itemNum++;
   445|    activityItems.push({
   446|      itemNumber: itemNum,
   447|      agent: 'Senior Developer',
   448|      department: 'Engineering',
   449|      category: 'DEVELOPMENT',
   450|      task: 'Developer proof recorded',
   451|      actionExecuted: 'Code change verified and proof recorded',
   452|      result: proof.verified ? 'VERIFIED' : 'UNVERIFIED',
   453|      status: proof.verified ? 'COMPLETED' : 'VERIFYING',
   454|      startTime: null,
   455|      endTime: null,
   456|      durationMs: null,
   457|      repository: 'ibb142/rork-global-real-estate-invest',
   458|      branch: 'main',
   459|      commitSha: proof.commitSha,
   460|      deploymentId: proof.deployId,
   461|      productionUrl: 'https://api.ivxholding.com',
   462|      investorId: null,
   463|      propertyId: null,
   464|      leadId: null,
   465|      error: null,
   466|      retryCount: 0,
   467|      evidence: `Proof ledger: ${proof.taskId}`,
   468|      traceId: proof.taskId,
   469|    });
   470|  }
   471|
   472|  // Add owner action requests as activity items
   473|  for (const action of ownerActions) {
   474|    itemNum++;
   475|    activityItems.push({
   476|      itemNumber: itemNum,
   477|      agent: 'Autonomous System',
   478|      department: 'Operations',
   479|      category: 'AUTONOMOUS_SYSTEM',
   480|      task: action.title,
   481|      actionExecuted: 'Owner action request created',
   482|      result: action.status,
   483|      status: action.status === 'verified' ? 'COMPLETED' : action.status === 'pending' ? 'OWNER_ACTION_REQUIRED' : 'BLOCKED',
   484|      startTime: action.createdAt,
   485|      endTime: null,
   486|      durationMs: null,
   487|      repository: null,
   488|      branch: null,
   489|      commitSha: null,
   490|      deploymentId: null,
   491|      productionUrl: null,
   492|      investorId: null,
   493|      propertyId: null,
   494|      leadId: null,
   495|      error: action.blocker,
   496|      retryCount: 0,
   497|      evidence: `Owner action: ${action.traceId}`,
   498|      traceId: action.traceId,
   499|    });
   500|  }
   501|
   502|  // Apply filters
   503|  let filteredItems = activityItems;
   504|  if (agentFilter && agentFilter !== 'all') {
   505|    filteredItems = filteredItems.filter((i) => i.agent.toLowerCase().includes(agentFilter.toLowerCase()));
   506|  }
   507|  if (categoryFilter && categoryFilter !== 'all') {
   508|    filteredItems = filteredItems.filter((i) => i.category === categoryFilter);
   509|  }
   510|
   511|  // Build category breakdown
   512|  const categories: ActivityCategory[] = ['DEVELOPMENT', 'INVESTORS', 'BUYERS', 'LEADS_CRM', 'PROPERTIES_DEALS', 'MARKETING', 'FINANCIAL', 'AUTONOMOUS_SYSTEM'];
   513|  const categoryBreakdown: CategorySummary[] = categories.map((cat) => {
   514|    const items = activityItems.filter((i) => i.category === cat);
   515|    return {
   516|      category: cat,
   517|      total: items.length,
   518|      completed: items.filter((i) => i.status === 'COMPLETED').length,
   519|      failed: items.filter((i) => i.status === 'FAILED').length,
   520|      blocked: items.filter((i) => i.status === 'BLOCKED' || i.status === 'OWNER_ACTION_REQUIRED').length,
   521|      items,
   522|    };
   523|  });
   524|
   525|  // Build live activity feed
   526|  const liveActivityFeed = agentRuns
   527|    .filter((r) => r.status === 'running')
   528|    .map((r) => ({
   529|      time: r.startedAt,
   530|      agent: r.label,
   531|      department: DEPARTMENT_MAP[r.kind] ?? 'Autonomous',
   532|      currentAction: r.detail,
   533|      status: 'RUNNING' as AgentStatus,
   534|      progressPercent: 50,
   535|      traceId: r.id,
   536|      taskId: r.id,
   537|    }));
   538|
   539|  // Build daily summary from report
   540|  let dailySummary: DailySummary | null = null;
   541|  if (latestReport) {
   542|    const r = latestReport.report;
   543|    const sections = r.sections;
   544|    const allFindings = Object.values(sections).flatMap((s) => s.findings);
   545|    dailySummary = {
   546|      reportDate: r.reportDate,
   547|      totalTasksStarted: agentRuns.filter((a) => isToday(a.startedAt)).length,
   548|      totalTasksCompleted: agentRuns.filter((a) => a.status === 'completed' && isToday(a.finishedAt)).length,
   549|      totalTasksFailed: agentRuns.filter((a) => a.status === 'failed' && isToday(a.finishedAt)).length,
   550|      totalTasksBlocked: ownerActions.filter((a) => a.status === 'pending').length,
   551|      totalRetries: 0,
